mapper.select:
select t.script_id,t.script_id scriptId,t.scene_id,t.scene_id sceneId,t.status_cd,t.status_cd
statusCd,t.obj_name,t.obj_name objName,t.dsms_id,t.dsms_id dsmsId,t.community_id,t.community_id communityId,
t.create_time createTime,ds.js_content jsContent,ds.script_name scriptName,t.obj_id objId,t.obj_type objType,td1.name objTypeName
from dt_scene_obj_script t
left join dt_script ds on t.script_id = ds.script_id
LEFT JOIN t_dict td1 on t.obj_type = td1.status_cd and td1.table_name = 'dt_modal' and td1.table_columns = 'modal_type'

where 1 =1

    and t.script_id= #{scriptId}


    and t.scene_id= #{sceneId}


    and t.status_cd= #{statusCd}


    and t.obj_name= #{objName}


    and t.obj_id = #{objId}


    and t.obj_type= #{objType}


    and t.dsms_id= #{dsmsId}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

